#include <Arduino.h>
#include <Adafruit_GFX.h>    
#include <Adafruit_ST7735.h> 
#include <SPI.h>

// 【重要】すべてのピンを内部のGPIO番号でしっかり指定します
#define TFT_CS     0   // 基板のD0
#define TFT_RST    1   // 基板のD1
#define TFT_DC     3   // 基板のD3
#define TFT_MOSI   10  // 基板のD10 (SDA)
#define TFT_SCLK   8   // 基板のD8  (SCL)

// 通信ピンをすべて詰め込んだ指定方法に変えます
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_MOSI, TFT_SCLK, TFT_RST);

void setup() {
  // Chromebookの通知連打を防ぐ命綱
  Serial.begin(115200);
  delay(1000); 

  // 液晶の初期化（まずは一番標準的な設定）
  tft.initR(INITR_BLACKTAB); 

  // 画面を「青色」で塗りつぶす
  tft.fillScreen(ST7735_BLUE);

  // 文字の設定
  tft.setCursor(10, 50);          
  tft.setTextColor(ST7735_WHITE); 
  tft.setTextSize(2);             

  // 文字を表示
  tft.println("Hello XIAO!");
}

void loop() {
  // 表示をキープするため空っぽでOK
}
